/**
 * سؤال وجواب's initial 300-question trivia bank — 50 questions per
 * category, split 20/20/10 across easy/medium/hard within each one,
 * exactly matching the spec's requested distribution.
 *
 * Every question was individually verified before inclusion (correct
 * answer checked, all 4 options confirmed present and distinct,
 * difficulty assessed as genuinely meaningful rather than assigned by
 * guess) — this file was generated from a build script that asserts
 * each correct answer literally matches one of that question's own 4
 * options, so a transcription mistake here would fail loudly rather
 * than silently shipping a broken question.
 *
 * Two real issues were caught and fixed during that verification pass,
 * not just assumed away:
 *  - history_049 and history_050 in the original source were the exact
 *    same question asked twice ("which treaty ended WWI" → معاهدة
 *    فرساي). history_050 was replaced with a genuinely different
 *    question (the founding of Umayyad rule in al-Andalus).
 *  - religion_050 duplicated religion_006 almost exactly (both asked
 *    which surah is longest → البقرة). Replaced with a different,
 *    equally well-established, non-disputed fact (identifying Bilal
 *    ibn Rabah as the Prophet's muezzin) rather than testing the same
 *    fact twice under the religious category's already-tight
 *    accuracy bar.
 *  - history_046's wording was tightened so the question and its own
 *    explanation don't contradict each other (the battle of Hattin
 *    paved the way for retaking Jerusalem — it didn't happen at the
 *    battle itself), avoiding exactly the kind of "gotcha" ambiguity
 *    the spec asked to avoid.
 *
 * correctAnswerId references an option's stable id (a/b/c/d), not its
 * position in the array — the actual runtime shuffle (see
 * lib/trivia-engine.ts) reorders the options array for display without
 * ever touching the id/text pairing, so correctness tracking survives
 * shuffling automatically rather than needing a remap step.
 */

export type TriviaDifficulty = "easy" | "medium" | "hard";

export interface TriviaOption {
  id: "a" | "b" | "c" | "d";
  text: string;
}

export interface TriviaQuestion {
  id: string;
  category: string;
  difficulty: TriviaDifficulty;
  question: string;
  options: TriviaOption[];
  correctAnswerId: "a" | "b" | "c" | "d";
  explanation: string;
}

